code='''{
            let n = self.parent.len();
            if root_i == root_j { return; }
            let ri = self.rank[root_i];
            let rj = self.rank[root_j];
            if ri < rj {
                self.parent.set(root_i, root_j);
            } else if rj < ri {
                self.parent.set(root_j, root_i);
            } else if rj + 1 < n {
                self.parent.set(root_i, root_j);
                self.rank.set(root_j, rj + 1);
            } else {
                // no room to increment: rebuild with fresh ranks
                let mut k: usize = 0;
                while k < n
                    invariant
                        k <= n,
                        self.parent.len() == n,
                        self.rank.len() == n,
                        forall|m: usize| m < k ==> self.parent[m as int] == m && self.rank[m as int] == 0,
                        forall|m: usize| k <= m < n ==> self.parent[m as int] == old(self).parent[m as int],
                    decreases n - k
                {
                    self.parent.set(k, k);
                    self.rank.set(k, 0);
                    k += 1;
                }
                self.parent.set(root_i, root_j);
                self.rank.set(root_j, 1);
            }
        }'''
